// Package wordnet answers one question about two English words: can one stand
// in for the other? It is the only lexical knowledge the generic-v2 comparator
// uses, and it is deliberately GENERAL — Princeton WordNet 3.0, not a list
// written for any one kind of task — so that what the comparator knows about
// "book" and "reserve" it knows equally about "rent" and "hire" or "ship" and
// "send", in domains nobody wrote it for.
//
// The data is lexicon.tsv.gz, generated by scripts/wordnet/gen_lexicon.py and
// embedded in the binary, so a comparison needs no file, no network and no
// model, and gives the same answer on every node.
package wordnet

import (
	"bufio"
	"bytes"
	"compress/gzip"
	_ "embed"
	"strconv"
	"strings"
	"sync"
)

//go:embed lexicon.tsv.gz
var raw []byte

type lexicon struct {
	synsets    map[string][]int32
	exceptions map[string]string
}

var (
	once sync.Once
	lex  *lexicon
)

func load() *lexicon {
	once.Do(func() {
		l := &lexicon{synsets: make(map[string][]int32, 80000), exceptions: make(map[string]string, 6000)}
		zr, err := gzip.NewReader(bytes.NewReader(raw))
		if err != nil {
			panic("wordnet: embedded lexicon is not gzip: " + err.Error())
		}
		sc := bufio.NewScanner(zr)
		sc.Buffer(make([]byte, 1<<20), 1<<20)
		for sc.Scan() {
			parts := strings.Split(sc.Text(), "\t")
			if len(parts) != 3 {
				continue
			}
			switch parts[0] {
			case "S":
				ids := strings.Split(parts[2], ",")
				v := make([]int32, 0, len(ids))
				for _, s := range ids {
					n, err := strconv.Atoi(s)
					if err == nil {
						v = append(v, int32(n))
					}
				}
				l.synsets[parts[1]] = v
			case "X":
				l.exceptions[parts[1]] = parts[2]
			}
		}
		lex = l
	})
	return lex
}

// Known reports whether w (or a base form of it) is an English word WordNet
// lists.
func Known(w string) bool {
	l := load()
	for _, b := range Bases(w) {
		if _, ok := l.synsets[b]; ok {
			return true
		}
	}
	return false
}

// detachment rules from WordNet's morphy, all parts of speech together.
var detach = [][2]string{
	{"ies", "y"}, {"ses", "s"}, {"xes", "x"}, {"zes", "z"}, {"ches", "ch"}, {"shes", "sh"},
	{"men", "man"}, {"es", "e"}, {"es", ""}, {"s", ""},
	{"ing", "e"}, {"ing", ""}, {"ed", "e"}, {"ed", ""},
	{"er", ""}, {"er", "e"}, {"est", ""}, {"est", "e"},
}

// Bases returns the word itself and every base form WordNet's morphology
// rules reach that is a real lemma, most specific first. "stolen" gives
// "steal", "tablets" gives "tablet", "booking" gives "booking" and "book".
func Bases(w string) []string {
	l := load()
	out := []string{w}
	seen := map[string]bool{w: true}
	add := func(b string) {
		if b != "" && !seen[b] {
			if _, ok := l.synsets[b]; ok {
				seen[b] = true
				out = append(out, b)
			}
		}
	}
	if b, ok := l.exceptions[w]; ok {
		add(b)
	}
	for _, r := range detach {
		if strings.HasSuffix(w, r[0]) && len(w) > len(r[0])+1 {
			stem := w[:len(w)-len(r[0])] + r[1]
			add(stem)
			// doubled consonant: "planned" -> "plann" -> "plan"
			if r[1] == "" && len(stem) > 2 && stem[len(stem)-1] == stem[len(stem)-2] {
				add(stem[:len(stem)-1])
			}
		}
	}
	return out
}

// Synonyms reports whether some base form of a and some base form of b are
// lemmas of one WordNet synset, in any part of speech. Equal words are
// synonyms trivially.
func Synonyms(a, b string) bool {
	if a == b {
		return true
	}
	l := load()
	ba, bb := Bases(a), Bases(b)
	for _, x := range ba {
		for _, y := range bb {
			if x == y {
				return true
			}
		}
	}
	for _, x := range ba {
		sx := l.synsets[x]
		if len(sx) == 0 {
			continue
		}
		for _, y := range bb {
			if shares(sx, l.synsets[y]) {
				return true
			}
		}
	}
	return false
}

func shares(a, b []int32) bool {
	for _, x := range a {
		for _, y := range b {
			if x == y {
				return true
			}
		}
	}
	return false
}
